package main

import (
	"fmt"
	"time"
)

const (
	step     = 10 * time.Millisecond  // fixed simulation step: 100 updates per second
	maxFrame = 100 * time.Millisecond // never simulate more than this per frame
	speed    = 50.0                   // units per second
)

// Clock is the only source of time the loop sees.
type Clock interface {
	Now() time.Duration
}

// scriptedClock replays recorded frame durations instead of reading the OS clock.
type scriptedClock struct {
	now    time.Duration
	frames []time.Duration
}

func (c *scriptedClock) Now() time.Duration { return c.now }

func (c *scriptedClock) Advance() bool {
	if len(c.frames) == 0 {
		return false
	}
	c.now += c.frames[0]
	c.frames = c.frames[1:]
	return true
}

type State struct{ X float64 }

func integrate(s State, dt time.Duration) State {
	s.X += speed * dt.Seconds()
	return s
}

type Loop struct {
	clock      Clock
	last       time.Duration
	acc        time.Duration
	prev, curr State
	steps      int
	dropped    time.Duration
}

type Report struct {
	Raw, Used time.Duration
	Steps     int
	Alpha     float64
	Drawn     State
}

func (l *Loop) Frame() Report {
	now := l.clock.Now()
	r := Report{Raw: now - l.last}
	l.last = now
	r.Used = min(r.Raw, maxFrame)
	l.dropped += r.Raw - r.Used
	l.acc += r.Used
	for l.acc >= step {
		l.prev = l.curr
		l.curr = integrate(l.curr, step)
		l.acc -= step
		r.Steps++
	}
	l.steps += r.Steps
	r.Alpha = float64(l.acc) / float64(step)
	r.Drawn = State{X: l.prev.X + (l.curr.X-l.prev.X)*r.Alpha}
	return r
}

func main() {
	ms := func(v ...int) []time.Duration {
		out := make([]time.Duration, len(v))
		for i, n := range v {
			out[i] = time.Duration(n) * time.Millisecond
		}
		return out
	}
	clock := &scriptedClock{frames: ms(16, 16, 16, 33, 4, 250, 16)}
	loop := &Loop{clock: clock}
	for n := 1; clock.Advance(); n++ {
		r := loop.Frame()
		dt := r.Raw.String()
		if r.Used != r.Raw {
			dt += " clamped to " + r.Used.String()
		}
		fmt.Printf("frame %d: %s, steps=%d alpha=%.2f draw x=%.2f\n", n, dt, r.Steps, r.Alpha, r.Drawn.X)
	}
	fmt.Printf("%d steps simulated %v; %v dropped of %v\n",
		loop.steps, time.Duration(loop.steps)*step, loop.dropped, clock.Now())
}

// monotonic adapts the OS clock to the Clock interface.
type monotonic struct{ start time.Time }

func (m monotonic) Now() time.Duration { return time.Since(m.start) }

func main() {
	loop := &Loop{clock: monotonic{start: time.Now()}}
	for !quit() {
		r := loop.Frame()
		render(r.Drawn)
	}
}

package main

import (
	"errors"
	"fmt"
)

// Screen stands in for *ebiten.Image: Draw writes to it and nothing else.
type Screen struct {
	W, H int
	Text string
}

// Game has the same three methods as ebiten.Game, with the headless Screen.
type Game interface {
	Update() error
	Draw(screen *Screen)
	Layout(outsideWidth, outsideHeight int) (screenWidth, screenHeight int)
}

// Termination plays the role of ebiten.Termination: stop without an error.
var Termination = errors.New("regular termination")

// Drone changes state only in Update, one tick at a time.
type Drone struct {
	Tick, X, Goal int
}

func (d *Drone) Update() error {
	d.Tick++
	d.X += 2
	if d.Goal > 0 && d.X >= d.Goal {
		return Termination
	}
	return nil
}

func (d *Drone) Draw(s *Screen) { s.Text = fmt.Sprintf("tick=%d x=%d", d.Tick, d.X) }

func (d *Drone) Layout(outsideWidth, outsideHeight int) (int, int) { return 320, 180 }

// DrawDrone moves inside Draw, so its speed follows the display.
type DrawDrone struct{ Drone }

func (d *DrawDrone) Update() error { d.Tick++; return nil }

func (d *DrawDrone) Draw(s *Screen) {
	d.X += 2
	d.Drone.Draw(s)
}

var errDiskFull = errors.New("disk full")

// Saver fails on its third tick, the way a real I/O error would surface.
type Saver struct{ Drone }

func (s *Saver) Update() error {
	s.Tick++
	if s.Tick == 3 {
		return fmt.Errorf("autosave: %w", errDiskFull)
	}
	return nil
}

// run is a headless stand-in for ebiten.RunGame. Each schedule entry is one
// frame: Layout, then that many Update calls, then one Draw.
func run(g Game, schedule []int) (frames, ticks int, screen Screen, err error) {
	for _, updates := range schedule {
		screen.W, screen.H = g.Layout(1920, 1080)
		for range updates {
			ticks++
			if err := g.Update(); err != nil {
				if errors.Is(err, Termination) {
					return frames, ticks, screen, nil
				}
				return frames, ticks, screen, err
			}
		}
		g.Draw(&screen)
		frames++
	}
	return frames, ticks, screen, nil
}

func repeat(pattern []int, times int) []int {
	var out []int
	for range times {
		out = append(out, pattern...)
	}
	return out
}

func main() {
	displays := []struct {
		name     string
		schedule []int
	}{
		{"60 Hz", repeat([]int{1}, 6)},
		{"120 Hz", repeat([]int{1, 0}, 6)},
		{"30 Hz", repeat([]int{2}, 3)},
	}
	for _, d := range displays {
		frames, ticks, screen, _ := run(&Drone{}, d.schedule)
		_, _, drawn, _ := run(&DrawDrone{}, d.schedule)
		fmt.Printf("%-6s %2d frames, %d ticks: Update-driven %q, Draw-driven %q\n",
			d.name, frames, ticks, screen.Text, drawn.Text)
	}
	_, ticks, screen, err := run(&Drone{Goal: 20}, repeat([]int{1}, 60))
	fmt.Printf("goal: Termination on tick %d, last frame %q at %dx%d, err=%v\n",
		ticks, screen.Text, screen.W, screen.H, err)
	_, ticks, _, err = run(&Saver{}, repeat([]int{1}, 60))
	fmt.Printf("saver: stopped on tick %d, err=%v, disk full=%t\n", ticks, err, errors.Is(err, errDiskFull))
}

import (
	"fmt"
	"image/color"
	"log"

	"github.com/hajimehoshi/ebiten/v2"
	"github.com/hajimehoshi/ebiten/v2/ebitenutil"
)

type Game struct {
	tick   int
	x      float64
	sprite *ebiten.Image // created once in main, never inside Draw
}

var _ ebiten.Game = (*Game)(nil)

func (g *Game) Update() error {
	if ebiten.IsKeyPressed(ebiten.KeyEscape) {
		return ebiten.Termination // RunGame returns nil
	}
	g.tick++
	g.x += 2
	if g.x > 320 {
		g.x = -16
	}
	return nil
}

func (g *Game) Draw(screen *ebiten.Image) {
	screen.Fill(color.RGBA{0x10, 0x18, 0x20, 0xff})
	op := &ebiten.DrawImageOptions{}
	op.GeoM.Translate(g.x, 82)
	screen.DrawImage(g.sprite, op)
	ebitenutil.DebugPrint(screen, fmt.Sprintf("tick %d", g.tick))
}

func (g *Game) Layout(outsideWidth, outsideHeight int) (int, int) {
	return 320, 180 // logical pixels; Ebitengine scales them to the window
}

func main() {
	sprite := ebiten.NewImage(16, 16)
	sprite.Fill(color.RGBA{0x00, 0xad, 0xd8, 0xff})
	ebiten.SetWindowSize(960, 540)
	ebiten.SetWindowTitle("Drone")
	if err := ebiten.RunGame(&Game{sprite: sprite}); err != nil {
		log.Fatal(err)
	}
}

func (g *Game) Update() error {
	in := Input{
		Left:  ebiten.IsKeyPressed(ebiten.KeyArrowLeft),
		Right: ebiten.IsKeyPressed(ebiten.KeyArrowRight),
	}
	return g.world.Step(in) // plain Go below this line: no ebiten imports
}

func (g *Game) Draw(screen *ebiten.Image) {
	frame := g.world.Tick / 8 % 4 // animation derived from ticks, not counted here
	g.drawPlayer(screen, frame)
}

package main

import (
	"fmt"
	"math"
)

// Vec2 is small and immutable in use: every method takes and returns values.
type Vec2 struct{ X, Y float64 }

func (a Vec2) Add(b Vec2) Vec2      { return Vec2{a.X + b.X, a.Y + b.Y} }
func (a Vec2) Scale(k float64) Vec2 { return Vec2{a.X * k, a.Y * k} }
func (a Vec2) Len() float64         { return math.Hypot(a.X, a.Y) }

// Normalize returns a unit vector, or the zero vector when there is no direction.
func (a Vec2) Normalize() Vec2 {
	l := a.Len()
	if l == 0 {
		return Vec2{}
	}
	return a.Scale(1 / l)
}

func (a Vec2) String() string { return fmt.Sprintf("(%.2f, %.2f)", a.X, a.Y) }

// Tuning values are per tick at a fixed 60 ticks per second.
const (
	tps       = 60
	accel     = 0.6  // px/tick gained per tick while input is held
	drag      = 0.8  // velocity multiplier applied every tick
	stopBelow = 0.05 // px per tick; snap tiny speeds to zero
)

type Body struct{ Pos, Vel Vec2 }

func (b *Body) Step(input Vec2) {
	b.Vel = b.Vel.Add(input.Normalize().Scale(accel)).Scale(drag)
	if b.Vel.Len() < stopBelow {
		b.Vel = Vec2{}
	}
	b.Pos = b.Pos.Add(b.Vel) // semi-implicit Euler: new velocity, then position
}

func main() {
	raw := Vec2{1, 1} // right + down held together
	fmt.Printf("raw input %v length %.2f\n", raw, raw.Len())
	fmt.Printf("unit dir  %v length %.2f\n", raw.Normalize(), raw.Normalize().Len())

	var b Body
	for tick := 1; tick <= 60; tick++ {
		input := Vec2{}
		if tick <= 12 {
			input = raw
		}
		b.Step(input)
		stopped := tick > 12 && b.Vel == (Vec2{})
		if tick <= 3 || tick == 12 || tick == 13 || tick == 20 || stopped {
			fmt.Printf("tick %2d pos=%v speed=%.3f px/tick\n", tick, b.Pos, b.Vel.Len())
		}
		if stopped {
			break
		}
	}
	terminal := accel * drag / (1 - drag)
	fmt.Printf("terminal speed %.2f px/tick = %.0f px/s at %d TPS\n", terminal, terminal*tps, tps)
	fmt.Printf("without Normalize the diagonal tops out at %.2f px/tick\n", terminal*raw.Len())
}

// The compiler may fuse this into one multiply-add on some targets:
next := pos + vel*dt
// The explicit conversion forces vel*dt to be rounded first, forbidding fusion:
next = pos + float64(vel*dt)

package main

import "fmt"

// Key names a physical control; Ebitengine would use ebiten.Key values.
type Key string

// Action is a bit set, so one tick's input is a single comparable value.
type Action uint8

const (
	Left Action = 1 << iota
	Right
	Jump
)

// bindings maps physical keys to actions; several keys may share an action.
var bindings = map[Key]Action{
	"ArrowLeft": Left, "KeyA": Left,
	"ArrowRight": Right, "KeyD": Right,
	"Space": Jump, "KeyW": Jump, "PadSouth": Jump,
}

// Input holds this tick's actions and the previous tick's.
type Input struct{ down, prev Action }

func (in *Input) Poll(keys []Key) {
	in.prev, in.down = in.down, 0
	for _, k := range keys {
		in.down |= bindings[k]
	}
}

func (in Input) Pressed(a Action) bool     { return in.down&a != 0 }
func (in Input) JustPressed(a Action) bool { return in.down&^in.prev&a != 0 }

const (
	gravity     = 1
	jumpSpeed   = 5
	coyoteTicks = 4 // a jump is still allowed this many ticks after leaving the floor
	bufferTicks = 5 // a jump press is remembered this many ticks
)

func floorAt(x int) int {
	switch {
	case x < 12:
		return 0
	case x < 30:
		return -10
	default:
		return -100
	}
}

type Player struct {
	X, Y, VY int
	air      int  // ticks since the feet last touched the floor
	jumped   bool // this airtime began with a jump, so coyote time is spent
	press    int  // ticks since an unused jump press; -1 when none is pending
}

func (p *Player) Tick(in Input) (event string) {
	if in.JustPressed(Jump) {
		p.press = 0
		if p.air > 0 {
			event = fmt.Sprintf("jump pressed %d ticks off the floor", p.air)
		}
	}
	if p.press >= 0 {
		switch {
		case !p.jumped && p.air <= coyoteTicks:
			event = fmt.Sprintf("jump: pressed %d ticks ago, %d ticks off the floor", p.press, p.air)
			p.VY, p.jumped, p.press = jumpSpeed, true, -1
		case p.press >= bufferTicks:
			event, p.press = "buffered press expired", -1
		default:
			p.press++
		}
	}
	if in.Pressed(Right) {
		p.X++
	}
	if in.Pressed(Left) {
		p.X--
	}
	p.VY -= gravity
	p.Y += p.VY
	if f := floorAt(p.X); p.Y <= f {
		if p.air > 0 && event == "" {
			event = fmt.Sprintf("landed at x=%d y=%d", p.X, f)
		}
		p.Y, p.VY, p.air, p.jumped = f, 0, 0, false
	} else {
		p.air++
	}
	return event
}

type hold struct {
	key      Key
	from, to int // inclusive ticks
}

func keysAt(script []hold, tick int) []Key {
	var keys []Key
	for _, h := range script {
		if tick >= h.from && tick <= h.to {
			keys = append(keys, h.key)
		}
	}
	return keys
}

func main() {
	script := []hold{
		{"Space", 2, 14},     // hold through landing: one jump, not a bounce
		{"KeyW", 6, 7},       // second jump key while Space is held: no new edge
		{"Space", 17, 17},    // tap on the floor
		{"PadSouth", 24, 24}, // pressed just before landing: buffered
		{"KeyD", 30, 75},     // run right toward two ledges
		{"Space", 43, 43},    // two ticks after walking off: coyote jump
		{"Space", 65, 65},    // six ticks after the next ledge: too late
	}
	p := &Player{press: -1}
	var in Input
	keyEdges, actionEdges := 0, 0
	held := map[Key]bool{}
	for tick := 1; tick <= 75; tick++ {
		keys := keysAt(script, tick)
		now := map[Key]bool{}
		for _, k := range keys {
			if !held[k] && bindings[k] == Jump {
				keyEdges++
			}
			now[k] = true
		}
		held = now
		in.Poll(keys)
		if in.JustPressed(Jump) {
			actionEdges++
		}
		if ev := p.Tick(in); ev != "" {
			fmt.Printf("tick %2d: %s\n", tick, ev)
		}
	}
	fmt.Printf("jump keys went down %d times; the Jump action had %d edges\n", keyEdges, actionEdges)
}

var jumpKeys = []ebiten.Key{ebiten.KeySpace, ebiten.KeyW, ebiten.KeyArrowUp}

func pollActions() Action {
	var a Action
	for _, k := range jumpKeys {
		if ebiten.IsKeyPressed(k) {
			a |= Jump
		}
	}
	if ebiten.IsKeyPressed(ebiten.KeyArrowLeft) || ebiten.IsKeyPressed(ebiten.KeyA) {
		a |= Left
	}
	if ebiten.IsKeyPressed(ebiten.KeyArrowRight) || ebiten.IsKeyPressed(ebiten.KeyD) {
		a |= Right
	}
	return a
}

func (g *Game) Update() error {
	g.in.prev, g.in.down = g.in.down, pollActions()
	g.player.Tick(g.in)
	return nil
}

